/**
 * ScoreAlignmentCorrectionRequest
 *
 * Human fallback: join the currently audible source time to one score beat.
 *
 * When the performer picked a specific reference onset (Mode B), pass its exact
 * ``source_midi_tick`` so the correction *selects* that onset instead of
 * re-interpolating it from ``source_seconds`` -- the latter only matches when
 * the reference tempo is constant, and silently drifts when it is not.
 */
export const zScoreAlignmentCorrectionRequest = z.object({
    beat_in_measure: z.number().gte(0),
    measure: z.int().gte(1),
    note: z.string().max(500).nullish(),
    source_midi_tick: z.int().gte(0).nullish(),
    source_seconds: z.number().gte(0),
    take_id: z.string().nullish()
}).register(z.globalRegistry, {
    description: 'Human fallback: join the currently audible source time to one score beat.\n\nWhen the performer picked a specific reference onset (Mode B), pass its exact\n``source_midi_tick`` so the correction *selects* that onset instead of\nre-interpolating it from ``source_seconds`` -- the latter only matches when\nthe reference tempo is constant, and silently drifts when it is not.'
});

/**
 * ScoreAlignmentCorrectionResponse
 */
export const zScoreAlignmentCorrectionResponse = z.object({
    beat_in_measure: z.number().gte(0),
    correction_id: z.string(),
    mapping_id: z.string(),
    measure: z.int().gte(1),
    measure_label: z.string(),
    reanalysis_queued: z.boolean().optional().default(false),
    score_tick: z.int().gte(0),
    source_midi_tick: z.int().gte(0),
    source_seconds: z.number().gte(0)
});

/**
 * ScoreHealthFindingResponse
 *
 * One disagreement between independently-derived views of the bundle.
 *
 * Each derived artifact validates on load, so a bundle can be entirely
 * "valid" while its measure grid, PDF geometry and reference warp describe
 * different music. These findings exist so that disagreement is visible
 * instead of surfacing as a cursor in the wrong bar.
 */
export const zScoreHealthFindingResponse = z.object({
    code: z.string(),
    measures: z.array(z.string()).optional().default([]),
    message: z.string(),
    severity: z.enum(['error', 'warning'])
}).register(z.globalRegistry, {
    description: 'One disagreement between independently-derived views of the bundle.\n\nEach derived artifact validates on load, so a bundle can be entirely\n"valid" while its measure grid, PDF geometry and reference warp describe\ndifferent music. These findings exist so that disagreement is visible\ninstead of surfacing as a cursor in the wrong bar.'
});

/**
 * ScoreBundleHealthResponse
 *
 * Which DVC-tracked score bundle artifacts haven't been pulled yet.
 *
 * Surfaced on the Ready face so a missing `dvc pull` shows up as a warning
 * instead of a silent PDF load failure discovered mid-session (rubato#101).
 */
export const zScoreBundleHealthResponse = z.object({
    findings: z.array(zScoreHealthFindingResponse).optional().default([]),
    missing_artifacts: z.array(z.string()),
    movement: z.int(),
    piece_id: z.string()
}).register(z.globalRegistry, {
    description: 'Which DVC-tracked score bundle artifacts haven\'t been pulled yet.\n\nSurfaced on the Ready face so a missing `dvc pull` shows up as a warning\ninstead of a silent PDF load failure discovered mid-session (rubato#101).'
});

